const events = $input.all().map(i => i.json).filter(Boolean);

const busy = [];
for (const e of events) {
  if (!e || !e.start || !e.end) continue;
  if (e.status === 'cancelled') continue;
  if (e.transparency === 'transparent') continue;
  if (!e.start.dateTime) continue;
  busy.push({ start: new Date(e.start.dateTime), end: new Date(e.end.dateTime) });
}
busy.sort((a, b) => a.start - b.start);

// All wall-clock reasoning in Europe/Berlin - luxon is available in code nodes as DateTime.
const ZONE = 'Europe/Berlin';
const nowDt = DateTime.now().setZone(ZONE);
const dayEndDt = nowDt.set({ hour: 22, minute: 0, second: 0, millisecond: 0 });
const endOfDayDt = dayEndDt > nowDt ? dayEndDt : nowDt;
const now = nowDt.toJSDate();
const endOfDay = endOfDayDt.toJSDate();

const free = [];
let cursor = now;
for (const b of busy) {
  if (b.end <= now) continue;
  if (b.start >= endOfDay) continue;
  const bStart = b.start > endOfDay ? endOfDay : b.start;
  const bEnd = b.end > endOfDay ? endOfDay : b.end;
  if (bStart > cursor) free.push({ start: new Date(cursor), end: new Date(bStart) });
  if (bEnd > cursor) cursor = new Date(bEnd);
}
if (cursor < endOfDay) free.push({ start: new Date(cursor), end: new Date(endOfDay) });

return free.map(w => ({
  json: { start: w.start.toISOString(), end: w.end.toISOString() }
}));

const weather = $input.first().json;
const form = $('On form submission').first().json;
const rawWindows = $('Compute free windows').all().map(i => ({
  start: new Date(i.json.start),
  end: new Date(i.json.end)
}));

const num = (v, d) => {
  const n = parseInt(String(v ?? '').trim().charAt(0), 10);
  return Number.isFinite(n) ? n : d;
};
const mood = num(form.Mood, 3);
const energy = num(form.Energy, 3);

const h = weather.hourly || {};
// Open-Meteo returns wall-clock times in the requested timezone (Europe/Amsterdam).
// Parse them in that zone - plain new Date(t) would treat them as UTC (2h off).
const hours = (h.time || []).map((t, i) => {
  const dt = DateTime.fromISO(String(t), { zone: 'Europe/Amsterdam' });
  return {
    time: dt.toJSDate(),
    localHour: dt.hour,
    temp: h.temperature_2m ? h.temperature_2m[i] : 15,
    precipProb: h.precipitation_probability ? h.precipitation_probability[i] : 0,
    precip: h.precipitation ? h.precipitation[i] : 0,
    wind: h.wind_speed_10m ? h.wind_speed_10m[i] : 0
  };
});

// Hard safety cutoff only - not a quality judgement. Anything this strict
// should never be left to a language model's discretion.
function unsafe(hr) {
  return hr.precipProb > 85 || hr.precip > 2.5 || hr.wind > 50;
}

const DAY_START = 7;
const DAY_END = 21;

let anySafeWeatherHour = false;
let anyFreeWindow = rawWindows.length > 0;

const candidates = [];
for (const w of rawWindows) {
  for (const hr of hours) {
    const hour = hr.localHour;
    if (hour < DAY_START || hour > DAY_END) continue;
    if (hr.time < w.start || hr.time >= w.end) continue;
    if (unsafe(hr)) continue;
    anySafeWeatherHour = true;
    const availableMinutes = Math.round((w.end.getTime() - hr.time.getTime()) / 60000);
    if (availableMinutes < 15) continue;
    candidates.push({
      windowStart: w.start.toISOString(),
      windowEnd: w.end.toISOString(),
      hour: hr.time.toISOString(),
      availableMinutes,
      temp: hr.temp,
      precipProbability: hr.precipProb,
      precipMm: hr.precip,
      windKmh: hr.wind
    });
  }
}

let blockedReasonIfEmpty = null;
if (candidates.length === 0) {
  if (!anyFreeWindow) blockedReasonIfEmpty = 'calendar_full';
  else if (!anySafeWeatherHour) blockedReasonIfEmpty = 'severe_weather';
  else blockedReasonIfEmpty = 'calendar_full'; // windows exist but all too short/fragmented
}

return [{
  json: {
    mood,
    energy,
    freeWindowCount: rawWindows.length,
    anyFreeWindow,
    anySafeWeatherHour,
    candidates,
    blockedReasonIfEmpty
  }
}];

