const prep = $('Prepare candidates').first().json;
const raw = $input.first().json;

const text =
  raw.message?.content ??
  raw.content ??
  raw.text ??
  raw.output ??
  (typeof raw === 'string' ? raw : JSON.stringify(raw));

function extractJson(s) {
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : s;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('No JSON object found in AI output');
  return JSON.parse(candidate.slice(start, end + 1));
}

let decision;
try {
  decision = extractJson(text);
} catch (e) {
  decision = {
    recommend: false,
    blockedReason: 'ai_parse_error',
    message:
      "Couldn't work out today's plan automatically - worth taking a short walk if you get a moment, weather permitting."
  };
}

const recommend = decision.recommend === true;

const validCandidate =
  recommend &&
  decision.slotStart &&
  prep.candidates.some(c => c.hour === new Date(decision.slotStart).toISOString());

let action = validCandidate ? 'outdoor' : 'none';
let activity = decision.activity === 'run' ? 'run' : 'walk';
let durationMin = Math.max(10, Math.min(60, parseInt(decision.durationMinutes, 10) || 30));
let slotStart, slotEnd;

const obstructedReasons = ['severe_weather', 'calendar_full', 'ai_parse_error'];
const effectiveBlockedReason = validCandidate
  ? null
  : (recommend ? 'ai_parse_error' : (decision.blockedReason || prep.blockedReasonIfEmpty));
const wasObstructed = !validCandidate && obstructedReasons.includes(effectiveBlockedReason);

if (validCandidate) {
  slotStart = new Date(decision.slotStart);
  slotEnd = decision.slotEnd ? new Date(decision.slotEnd) : new Date(slotStart.getTime() + durationMin * 60000);
} else if (wasObstructed) {
  // Getting outside was actually blocked (weather/calendar/error), not just
  // judged unnecessary - offer a short indoor reset if any calendar gap exists.
  const INDOOR_MIN = 10;
  const INDOOR_TARGET = 15;
  const rawWindows = $('Compute free windows').all()
    .map(i => ({ start: new Date(i.json.start), end: new Date(i.json.end) }))
    .filter(w => (w.end - w.start) / 60000 >= INDOOR_MIN)
    .sort((a, b) => a.start - b.start);

  if (rawWindows.length > 0) {
    const w = rawWindows[0];
    const available = Math.floor((w.end - w.start) / 60000);
    durationMin = Math.min(INDOOR_TARGET, available);
    slotStart = w.start;
    slotEnd = new Date(slotStart.getTime() + durationMin * 60000);
    activity = 'indoor';
    action = 'indoor';
  }
}
// else: AI judged it genuinely unnecessary today (e.g. good mood, poor weather) -
// action stays 'none', nothing gets blocked, message says it's fine to skip.

const out = {
  action,
  activity,
  durationMin,
  message: decision.message || 'Take it easy today.',
  reasoning: decision.reasoning || null,
  blockedReason: action === 'outdoor' ? null : effectiveBlockedReason,
  mood: prep.mood,
  energy: prep.energy,
  freeWindowCount: prep.freeWindowCount
};

if (slotStart) {
  out.slotStart = slotStart.toISOString();
  out.slotEnd = slotEnd.toISOString();
  const tzOpts = { hour: '2-digit', minute: '2-digit', timeZone: 'Europe/Berlin' };
  out.slotLabel = slotStart.toLocaleTimeString('en-GB', tzOpts) +
    '-' + slotEnd.toLocaleTimeString('en-GB', tzOpts);
}

return [{ json: out }];

